import {flowView,syncView,notificationsView,receiptView,safetyView,bindWorkflows} from './workflows.js';
import {execute,queueListing,synchronize,loadSharedPhoto} from './sync.js';
import {icon} from './icons.js';
import {MATERIALS,LOCALITIES,newId,shortId,getPrice,getHistory,getMovement,valuation,saveLot,cancelLot,evolvePrices,ledger,parseWeight} from './domain.js';
import {readState,changeState,getPhoto,compressPhoto} from './store.js';
import {translations,languageLocale} from './i18n.js';

let state,route='home',filter='all',form=null,dirty=false,busy=false,simOffline=false,auto=true,modal=null,toastTimer,photoURLs=[],offlineReady=false,renderToken=0;
const app=document.querySelector('#app');
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=key=>translations[state?.collector.language||'en'][key]||translations.en[key]||key;
const money=paise=>new Intl.NumberFormat(languageLocale[state?.collector.language||'en'],{style:'currency',currency:'INR',maximumFractionDigits:2,minimumFractionDigits:0}).format((paise||0)/100);
const date=(value,short=false)=>new Date(value).toLocaleString(languageLocale[state?.collector.language||'en'],short?{day:'numeric',month:'short'}:{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
const materialName=id=>id?t(id):t('untitled');
const badge=lot=>`<span class="badge ${lot.status==='draft'?'amber':lot.status==='cancelled'?'gray':''}">${t(lot.status)}</span>`;
const context=()=>({t,money,date,esc});
const localNotice=()=>`<div class="notice">${icon('info')}<span>${state.sync?.code?t('connectionNote'):t('localMode')}</span></div>`;
const button=(text,action,kind='secondary',ic='')=>`<button class="btn ${kind}" data-action="${action}">${ic?icon(ic):''}${text}</button>`;
function toast(text){clearTimeout(toastTimer);const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),5500);}
function heading(title,subtitle,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p class="muted">${subtitle}</p></div>${action}</div>`;}
function empty(title,body,cta=false){return `<div class="card empty-state"><div class="empty-icon">${icon('lots')}</div><h2>${title}</h2><p class="muted">${body}</p>${cta?`<a class="btn" href="#create">${icon('plus')}${t('newLot')}</a>`:''}</div>`;}
function sparkline(history,large=false){const values=history.map(p=>p.ratePaise);if(!values.length)return '';let min=Math.min(...values)*.99,max=Math.max(...values)*1.01;const points=values.map((v,i)=>`${(i/(Math.max(1,values.length-1))*500).toFixed(1)},${(90-(v-min)/(max-min)*80).toFixed(1)}`).join(' ');return `<svg class="${large?'history-chart':'sparkline'}" viewBox="0 0 500 100" preserveAspectRatio="none" role="img" aria-label="${esc(t('history'))}"><path d="M0 25h500M0 55h500M0 85h500" stroke="#e8eee9" stroke-width="1" fill="none"/><polygon points="0,100 ${points} 500,100" fill="#ecf5ed"/><polyline points="${points}" fill="none" stroke="#227450" stroke-width="2.5" vector-effect="non-scaling-stroke"/></svg>`;}
function priceCard(material){const p=getPrice(state,material.id,state.collector.locality);if(!p)return '';const movement=getMovement(state,material.id,state.collector.locality);return `<article class="card price-card"><div class="row between"><div class="row"><span class="material-icon ${material.id}">${icon(material.icon)}</span><div><h3>${t(material.id)}</h3><p class="muted small">${t(material.id+'Sub')}</p></div></div></div><div class="row between"><div class="price-value">${money(p.ratePaise)} <span>${t('perKg')}</span></div><span class="movement ${movement<0?'down':''}">${movement>=0?'↗':'↘'} ${Math.abs(movement).toFixed(1)}%</span></div><p class="muted small">${t('range')}: ${money(p.lowPaise)}–${money(p.highPaise)}</p>${sparkline(getHistory(state,material.id,state.collector.locality))}<div class="price-foot"><button class="text-link plain" data-action="history" data-material="${material.id}">${t('history')}${icon('arrow')}</button><button class="icon-btn" data-action="speak" data-material="${material.id}" aria-label="${t('listen')}: ${t(material.id)}">${icon('volume')}</button></div></article>`;}
function lotCard(lot){return `<a class="lot-card card" href="#lot/${lot.id}"><div class="lot-thumb" ${lot.photoId?`data-photo="${esc(lot.photoId)}"`:''}>${icon(lot.materialId||'lots')}</div><div class="lot-main"><div class="row between"><span class="small muted">${shortId(lot.id)}</span>${badge(lot)}${lot.isSample?'<span class="badge amber">SAMPLE</span>':''}</div><h3>${materialName(lot.materialId)}</h3><p class="small muted">${esc(lot.weight||'—')} kg · ${esc(lot.locality)}</p><div class="row between lot-bottom"><strong>${lot.estimate?`${money(lot.estimate.lowTotalPaise)}–${money(lot.estimate.highTotalPaise)}`:'—'}</strong><span class="small muted">${date(lot.updatedAt,true)}</span></div></div></a>`;}
function stats(){const totals=ledger(state);return `<div class="stats"><div class="stat"><div class="stat-label">${t('activeLots')}${icon('lots')}</div><strong>${state.lots.filter(l=>!['draft','cancelled','completed'].includes(l.status)).length.toString().padStart(2,'0')}</strong><span class="small muted">${t(state.sync?.code?'workspaceSync':'onDevice')}</span></div><div class="stat"><div class="stat-label">${t('drafts')}${icon('lots')}</div><strong>${state.lots.filter(l=>l.status==='draft').length.toString().padStart(2,'0')}</strong><span class="small muted">${t('onDevice')}</span></div><div class="stat"><div class="stat-label">${t('received')}${icon('wallet')}</div><strong>${money(totals.receivedPaise)}</strong><span class="small muted">${t('receivedConfirmed')}</span></div></div>`;}
function homeView(){return `${heading(t('heading'),t('intro'))}<section class="card" style="padding:20px;margin-bottom:20px"><h2>Photo identification demo</h2><p>20 aggregator categories · 106 recycler codes · ERP overview</p><a class="btn" href="./identify.html">Open identification demo</a></section><section class="hero"><div><span class="hero-label">${t('sell')}</span><h2>${t('heroTitle')}</h2><p>${t('heroBody')}</p><a class="btn lime" href="#create">${icon('plus')}${t('newLot')}</a></div><div class="hero-side"><strong>3</strong><span>${t('categories')}</span><strong class="spaced">${t('days')}</strong><span>${t('historyLabel')}</span></div></section>${stats()}<div class="section-title"><h2>${t('today')}</h2><a class="text-link" href="#prices">${t('allPrices')}${icon('arrow')}</a></div><div class="prices-grid">${MATERIALS.map(priceCard).join('')}</div><p class="updated-line muted small">${t('simulated')} · ${t('updated')} ${date(state.lastPriceUpdate)} · ${esc(state.collector.locality)}</p><div class="section-title below"><h2>${t('recent')}</h2><a class="text-link" href="#lots">${t('allLots')}${icon('arrow')}</a></div>${state.lots.length?`<div class="lots-grid">${state.lots.slice(0,3).map(lotCard).join('')}</div>`:empty(t('noLots'),t('noLotsBody'),false)}`;}
function pricesView(){return `${heading(t('pricesTitle'),t('pricesIntro'),button(t('refresh'),'refresh','secondary','prices'))}<div class="section-title"><span class="badge amber">${t('simulated')} · ₹/kg</span><span class="small muted">${esc(state.collector.locality)}</span></div><div class="prices-grid">${MATERIALS.map(priceCard).join('')}</div><div class="price-update card"><div><strong>${t('updated')} ${date(state.lastPriceUpdate)}</strong><p class="small muted">${auto?t('auto'):t('autoUpdates')+': OFF'}</p></div><span class="badge gray">${t('vsYesterday')}</span></div><div class="notice">${icon('info')}<span>${t('priceNotice')}</span></div>`;}
function lotsView(buyer=false){const lots=state.lots.filter(l=>buyer?l.status==='listed':filter==='all'||l.status===filter);return `${heading(t(buyer?'buyerTitle':'lotsTitle'),t(buyer?'buyerIntro':'lotsIntro'),buyer?'':`<a class="btn" href="#create">${icon('plus')}${t('newLot')}</a>`)}${buyer?'':`<div class="tabs" role="group" aria-label="${t('lots')}">${['all','draft','listed','accepted','pickup','awaiting_confirmation','payment_due','completed','cancelled'].map(f=>`<button class="${filter===f?'selected':''}" data-action="filter" data-filter="${f}">${t(f)} <span>${state.lots.filter(l=>f==='all'||l.status===f).length}</span></button>`).join('')}</div>`}${lots.length?`<div class="lots-grid">${lots.map(lotCard).join('')}</div>`:empty(t(buyer?'buyerEmpty':'emptyFilter'),t(buyer?'buyerNote':'noLotsBody'),!buyer)}${localNotice()}`;}
function earningsView(){const totals=ledger(state);return `${heading(t('earningsTitle'),t('earningsIntro'))}<div class="stats">${[['saleValue',totals.valuePaise],['received',totals.receivedPaise],['outstanding',totals.outstandingPaise]].map(([key,value])=>`<div class="stat"><div class="stat-label">${t(key)}${icon('wallet')}</div><strong>${money(value)}</strong></div>`).join('')}</div>${totals.sales.length?`<div class="lots-grid">${totals.sales.map(h=>lotCard(state.lots.find(l=>l.id===h.lotId))).join('')}</div>`:empty(t('earningsEmpty'),t('earningsBody'))}${localNotice()}`;}
async function reloadState(){state=await readState();if(!form&&!document.activeElement?.matches('[data-flow-field]'))render();}
function estimateContent(){const v=valuation(state,form.materialId,form.locality,form.weight);return `<span class="eyebrow">${t('estimate')}</span><div class="estimate-number">${v?`${money(v.lowTotalPaise)}<br/><span>– ${money(v.highTotalPaise)}</span>`:'—'}</div><p>${v?`${esc(form.weight)} kg × ${money(v.lowPaise)}–${money(v.highPaise)}/kg`:t('estimateEmpty')}</p>${v?`<p class="small muted">${t('estimateDate')}: ${date(v.priceAt)}</p>`:''}<div class="estimate-note">${icon('info')}<span>${t('estimateNote')}</span></div><span class="badge amber">${t('simulated')}</span>${form.materialId?safetyView(form.materialId,context()):''}`;}
function formView(){return `${heading(t(form.expectedVersion?'editLot':'newLotTitle'),t('newLotIntro'))}<form id="lot-form" novalidate><div class="form-layout"><div class="card form-card"><div class="field"><label>${t('photo')}</label><div class="upload-area" id="upload-area"><div class="upload-preview" id="upload-preview">${form.photoId?`<div class="preview-fill" data-photo="${esc(form.photoId)}"></div>`:icon('lots')}</div><strong>${t(form.photoId?'replacePhoto':'addPhoto')}</strong><p class="muted small">${t('photoHelp')}</p><div class="row upload-buttons"><label class="btn secondary upload-button" tabindex="0" role="button">${t('choosePhoto')}<input id="photo-upload" type="file" accept="image/jpeg,image/png,image/webp" /></label><label class="btn soft upload-button" tabindex="0" role="button">${t('takePhoto')}<input type="file" accept="image/jpeg,image/png,image/webp" capture="environment" /></label></div></div><span class="field-error" id="photo-error"></span></div><div class="field"><label for="material">${t('material')}</label><select id="material" name="materialId"><option value="">${t('chooseMaterial')}</option>${MATERIALS.map(m=>`<option value="${m.id}" ${form.materialId===m.id?'selected':''}>${t(m.id)} · ${t(m.id+'Sub')}</option>`).join('')}</select><span class="field-error" id="material-error"></span></div><div class="field-pair"><div class="field"><label for="weight">${t('weight')}</label><div class="input-unit"><input id="weight" name="weight" inputmode="decimal" autocomplete="off" placeholder="0.0" value="${esc(form.weight)}"/><span>kg</span></div><small class="muted">${t('weightHint')}</small><span class="field-error" id="weight-error"></span></div><div class="field"><label for="lot-locality">${t('locality')}</label><select name="locality" id="lot-locality">${LOCALITIES.map(l=>`<option ${form.locality===l?'selected':''}>${esc(l)}</option>`).join('')}</select></div></div><div class="field"><label for="condition">${t('condition')}</label><select name="condition" id="condition">${['unsorted','sorted','damaged'].map(c=>`<option value="${c}" ${form.condition===c?'selected':''}>${t(c)}</option>`).join('')}</select></div><div class="field"><label for="description">${t('description')}</label><textarea id="description" name="description" maxlength="500" rows="3" placeholder="${t('descriptionHint')}">${esc(form.description)}</textarea></div></div><aside><div class="card estimate-card" id="estimate-card">${estimateContent()}</div>${localNotice()}</aside></div><div class="form-actions"><a class="text-link" href="${form.expectedVersion?'#lot/'+form.id:'#lots'}">← ${t('back')}</a><div class="row">${button(t(form.status==='listed'?'saveChanges':'saveDraft'),'save','secondary')}${form.status!=='listed'?button(t('listLot'),'publish','','arrow'):''}</div></div><p id="save-error" class="field-error" role="alert"></p></form>`;}
function lotView(id){const lot=state.lots.find(l=>l.id===id);if(!lot)return empty(t('notFound'),'');const current=valuation(state,lot.materialId,lot.locality,lot.weight);const snapshots=lot.originalEstimate||lot.estimate;return `<a class="text-link breadcrumb" href="#lots">← ${t('lots')}</a>${heading(materialName(lot.materialId),`${shortId(lot.id)} · ${t('created')} ${date(lot.createdAt)}`,badge(lot))}<div class="detail-layout"><div><section class="card detail-card"><div class="detail-photo" ${lot.photoId?`data-photo="${esc(lot.photoId)}"`:''}>${icon(lot.materialId||'lots')}<span>${t('noPhoto')}</span></div><div class="detail-fields"><div><span>${t('weightEstimated')}</span><strong>${esc(lot.weight||'—')} kg</strong></div><div><span>${t('locality')}</span><strong>${esc(lot.locality)}</strong></div><div><span>${t('material')}</span><strong>${lot.materialId?t(lot.materialId+'Sub'):t('noMaterial')}</strong></div><div><span>${t('condition')}</span><strong>${t(lot.condition)}</strong></div></div>${lot.description?`<p class="description-text">${esc(lot.description)}</p>`:''}<div class="detail-actions">${['draft','listed'].includes(lot.status)?`<a class="btn secondary" href="#edit/${lot.id}">${t('edit')}</a>${button(t('cancelLot'),'cancel','danger')}`:''}<span class="badge gray">${t(lot.storage==='synced'?'synced':lot.storage==='waiting'?'waiting':'device')}</span></div></section>${flowView(state,lot,context())}<section class="card timeline"><h2>${t('activity')}</h2>${state.events.filter(e=>e.lotId===id).slice().sort((a,b)=>b.at.localeCompare(a.at)).map(e=>`<div class="timeline-item"><span class="timeline-dot"></span><div><strong>${t({created:'eventCreated',listed:'eventListed',updated:'eventUpdated',cancelled:'eventCancelled'}[e.type]||e.type)}</strong><p class="small muted">${date(e.at)}</p></div></div>`).join('')}</section></div><aside><section class="card estimate-card"><span class="eyebrow">${t(lot.originalEstimate?'listedEstimate':'savedEstimate')}</span><div class="estimate-number">${snapshots?`${money(snapshots.lowTotalPaise)}<br/><span>– ${money(snapshots.highTotalPaise)}</span>`:'—'}</div>${snapshots?`<p class="small muted">${t('estimateDate')}: ${date(snapshots.priceAt)}</p>`:''}<div class="divider"></div><span class="small muted">${t('currentEstimate')}</span><h3 class="current-value">${current?`${money(current.lowTotalPaise)}–${money(current.highTotalPaise)}`:'—'}</h3><p class="small muted">${t('estimateNote')}</p><span class="badge amber">${t('simulated')}</span></section><div class="notice">${icon('info')}<span>${t('detailsNote')}</span></div></aside></div>${localNotice()}`;}
function demoView(){return `${heading(t('demoTitle'),t('demo'))}${syncView(state,context())}<section class="card transaction-card"><h2>${t('sampleData')}</h2><p>${t('simulationNote')}</p><button class="btn secondary" data-sample="seed">${t('addSample')}</button><button class="btn danger" data-sample="reset">${t('resetSamples')}</button></section><div class="card demo-card"><h2>${t('demoControls')}</h2><div class="demo-row"><div><strong>${t('refresh')}</strong><p class="small muted">${t('priceNotice')}</p></div>${button(t('refresh'),'refresh','','prices')}</div><label class="demo-row"><span>${t('autoUpdates')}</span><input type="checkbox" id="auto-toggle" ${auto?'checked':''}/></label><label class="demo-row"><div><strong>${t('simulateOffline')}</strong><p class="small muted">${t('offlineHelp')}</p></div><input type="checkbox" id="offline-toggle" ${simOffline?'checked':''}/></label><div class="demo-row"><div><strong>${t('buyer')}</strong><p class="small muted">${t('buyerIntro')}</p></div><a class="btn secondary" href="#buyer">${t('buyer')}${icon('arrow')}</a></div></div><h2 class="below">${t('storeSummary')}</h2><div class="stats">${[['lotsCount',state.lots.length],['eventsCount',state.events.length],['localPrices',state.prices.length]].map(([k,n])=>`<div class="stat"><span class="stat-label">${t(k)}</span><strong>${n}</strong></div>`).join('')}</div>${localNotice()}`;}
function render(){
  const openDetails=[...document.querySelectorAll('details[open]')].map(el=>el.querySelector('summary')?.textContent);
  renderToken++;photoURLs.forEach(URL.revokeObjectURL);photoURLs=[];
  document.documentElement.lang=state.collector.language;
  const active=route.startsWith('lot')||route.startsWith('edit')||route==='create'?'lots':route;
  let content=route==='notifications'?notificationsView(state,context()):route.startsWith('receipt/')?receiptView(state,route.slice(8),context()):route==='home'?homeView():route==='prices'?pricesView():route==='lots'?lotsView():route==='buyer'?lotsView(true):route==='wallet'?earningsView():route==='demo'?demoView():route==='create'||route.startsWith('edit/')?formView():route.startsWith('lot/')?lotView(route.slice(4)):homeView();
  app.innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="#home"><img src="./icon.svg" alt=""/><span>E-Waste<small>MARKETPLACE</small></span></a><nav class="nav" aria-label="Main navigation">${[['home','home'],['prices','prices'],['lots','lots'],['wallet','earnings']].map(([id,key])=>`<a href="#${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(id)}${t(key)}</a>`).join('')}</nav><div class="sidebar-bottom"><a class="text-link" href="#demo">${icon('settings')}${t('demoControls')}</a><span class="badge amber">${t('demo')}</span><div class="profile"><span class="avatar">C</span><div><strong>${t('collector')}</strong><div class="small muted">${esc(state.collector.locality)}</div></div></div></div></aside><main class="main"><header class="topbar"><span class="eyebrow">${t('workspace')}</span><a class="brand mobile-brand" href="#home"><img src="./icon.svg" alt=""/>E-Waste</a><div class="top-actions"><select class="location" id="global-locality" aria-label="${t('locality')}">${LOCALITIES.map(l=>`<option ${state.collector.locality===l?'selected':''}>${l}</option>`).join('')}</select><select class="language" id="language" aria-label="${t('language')}">${[['en','English'],['hi','हिन्दी'],['mr','मराठी']].map(([id,label])=>`<option value="${id}" ${state.collector.language===id?'selected':''}>${label}</option>`).join('')}</select><a class="icon-btn" href="#notifications" aria-label="${t('notifications')}">♧</a><a class="icon-btn" href="#demo" aria-label="${t('demoControls')}">${icon('settings')}</a></div></header><div class="connection-strip"><span>${simOffline?t('demoOffline'):navigator.onLine?(state.sync?.code?t(state.sync.error?'syncFailed':state.outbox?.length?'waiting':'synced'):t('localMode')):t('offline')} ${offlineReady?'· '+t('ready'):''}</span><a href="#${route==='buyer'?'home':'buyer'}">${t(route==='buyer'?'collectorView':'buyer')} →</a></div><div class="content">${content}</div></main></div><div id="modal-root"></div>`;
  for(const el of document.querySelectorAll('details'))if(openDetails.includes(el.querySelector('summary')?.textContent))el.open=true;
  hydratePhotos(renderToken);if(form?.photoBlob&&(route==='create'||route.startsWith('edit/')))showFormPhoto();if(modal)renderModal();
}
async function hydratePhotos(token){for(const el of document.querySelectorAll('[data-photo]')){try{const blob=await loadSharedPhoto(el.dataset.photo);if(!blob||token!==renderToken)continue;const url=URL.createObjectURL(blob);photoURLs.push(url);const img=document.createElement('img');img.src=url;img.alt=t('photo');el.replaceChildren(img);}catch{el.title=t('noPhoto');}}}
function showFormPhoto(){const el=document.querySelector('#upload-preview');if(!el||!form.photoBlob)return;const url=URL.createObjectURL(form.photoBlob);photoURLs.push(url);const img=document.createElement('img');img.src=url;img.alt=t('photo');el.replaceChildren(img);}
function readForm(){const el=document.querySelector('#lot-form');if(!el||!form)return;const data=new FormData(el);for(const key of ['materialId','weight','locality','condition','description'])form[key]=String(data.get(key)||'');}
function startForm(id){const lot=state.lots.find(l=>l.id===id);form=lot?{...lot,expectedVersion:lot.version}:{id:newId('lot'),materialId:'',weight:'',locality:state.collector.locality,description:'',condition:'unsorted',photoId:null};dirty=false;}
function navigate(){const next=location.hash.slice(1)||'home';if(next===route&&app.querySelector('.layout'))return;if(dirty&&!confirm(t('unsaved'))){history.replaceState(null,'','#'+route);return;}dirty=false;modal=null;route=next;if(route==='create')startForm();else if(route.startsWith('edit/')){const lot=state.lots.find(l=>l.id===route.slice(5));if(!lot||!['draft','listed'].includes(lot.status)){route='lots';history.replaceState(null,'','#lots');form=null;}else startForm(lot.id);}else form=null;render();window.scrollTo(0,0);}
async function save(publish){if(busy)return;readForm();let valid=true;for(const id of ['material-error','weight-error','photo-error','save-error'])document.getElementById(id).textContent='';if(publish||form.status==='listed'){for(const [test,id,key]of [[!form.materialId,'material-error','validationMaterial'],[!parseWeight(form.weight),'weight-error','validationWeight'],[!form.photoId,'photo-error','validationPhoto']])if(test){document.getElementById(id).textContent=t(key);valid=false;}}if(!valid){document.querySelector('.field-error:not(:empty)')?.scrollIntoView({block:'center',behavior:'smooth'});return;}
  busy=true;const buttons=[...document.querySelectorAll('#lot-form button')];buttons.forEach(b=>b.disabled=true);
  try{const result=await changeState(s=>{const previous=s.lots.find(l=>l.id===form.id);const lot=saveLot(s,form,{publish:publish||form.status==='listed'});if(lot.status==='listed')queueListing(s,lot,previous);return lot;},{photo:form.photoBlob?{id:form.photoId,blob:form.photoBlob}:undefined});state=result.state;dirty=false;form=null;toast(t(publish?'lotListed':'draftSaved'));location.hash='lot/'+result.result.id;if(state.sync?.code&&!simOffline&&navigator.onLine)synchronize().then(reloadState).catch(error=>toast(error.message));}catch(error){document.querySelector('#save-error').textContent=error.message||t('saveFailed');}finally{busy=false;buttons.forEach(b=>b.disabled=false);}
}
async function refresh(silent=false){if(busy||simOffline||!navigator.onLine){if(!silent)toast(t('offline'));return;}try{if(state.sync?.code){await synchronize();await execute({type:'prices'});await reloadState();return;}const r=await changeState(s=>evolvePrices(s));state=r.state;if(!form)render();else document.querySelector('#estimate-card').innerHTML=estimateContent();if(!silent)toast(t('refreshDone'));}catch{if(!silent)toast(t('saveFailed'));}}
function renderModal(){const root=document.querySelector('#modal-root');if(!modal){root.innerHTML='';return;}const isHistory=modal.type==='history';let content;
  if(isHistory){const history=getHistory(state,modal.materialId,state.collector.locality);content=`<h2 id="dialog-title">${t(modal.materialId)} · ${t('historyTitle')}</h2><p class="muted small">${state.collector.locality} · ${t('simulated')} ₹/kg</p>${sparkline(history,true)}<div class="row between small muted"><span>${date(history[0].at,true)}</span><span>${date(history.at(-1).at,true)}</span></div><p class="small muted below">${t('historyNote')}</p><details><summary>${t('historyList')}</summary><table><thead><tr><th>${t('date')}</th><th>${t('price')}</th></tr></thead><tbody>${history.slice().reverse().map(p=>`<tr><td>${date(p.at,true)}</td><td>${money(p.ratePaise)}</td></tr>`).join('')}</tbody></table></details>`;}else{content=`<h2 id="dialog-title">${t('cancelLot')}</h2><p class="muted below">${t('cancelQuestion')}</p><div class="row below">${button(t('keepLot'),'close')}${button(t('cancelYes'),'confirm-cancel','danger')}</div>`;}
  root.innerHTML=`<dialog aria-labelledby="dialog-title"><button class="modal-close icon-btn" data-action="close" aria-label="${t('close')}">✕</button>${content}</dialog>`;const dialog=root.querySelector('dialog');dialog.addEventListener('cancel',()=>{modal=null;});dialog.showModal();
}
function speak(materialId){const synth=window.speechSynthesis;if(!synth){toast(t('speechUnavailable'));return;}const lang=languageLocale[state.collector.language],voice=synth.getVoices().find(v=>v.lang.toLowerCase().startsWith(lang.split('-')[0]));if(!voice){toast(t('speechUnavailable'));return;}const p=getPrice(state,materialId,state.collector.locality);const utterance=new SpeechSynthesisUtterance(`${t('simulated')}. ${t(materialId)}. ${state.collector.locality}. ${money(p.ratePaise)} ${t('perKg')}. ${t('range')}: ${money(p.lowPaise)} ${money(p.highPaise)}.`);utterance.lang=lang;utterance.voice=voice;utterance.rate=.86;utterance.onerror=()=>toast(t('speechFailed'));synth.cancel();synth.speak(utterance);}
app.addEventListener('click',async event=>{const btn=event.target.closest('[data-action]');if(!btn)return;const action=btn.dataset.action;
  if(action==='save'||action==='publish'){event.preventDefault();return save(action==='publish');}
  if(action==='refresh')return refresh();
  if(action==='filter'){filter=btn.dataset.filter;return render();}
  if(action==='history'){modal={type:'history',materialId:btn.dataset.material};return renderModal();}
  if(action==='speak')return speak(btn.dataset.material);
  if(action==='cancel'){modal={type:'cancel',id:route.slice(4)};return renderModal();}
  if(action==='close'){modal=null;document.querySelector('dialog')?.close();return;}
  if(action==='confirm-cancel'){if(busy)return;busy=true;try{const r=await execute({type:'cancel',lotId:modal.id,expectedVersion:state.lots.find(l=>l.id===modal.id).version});state=r.state;modal=null;render();}catch(error){toast(error.message);}finally{busy=false;}}
  if(action==='retry')location.reload();
});
app.addEventListener('submit',event=>event.preventDefault());
app.addEventListener('input',event=>{if(event.target.closest('#lot-form')&&event.target.type!=='file'){dirty=true;readForm();document.querySelector('#estimate-card').innerHTML=estimateContent();}});
app.addEventListener('keydown',event=>{if(event.target.matches('.upload-button')&&['Enter',' '].includes(event.key)){event.preventDefault();event.target.querySelector('input').click();}});
app.addEventListener('change',async event=>{const el=event.target;
  if(el.id==='language'||el.id==='global-locality'){readForm();try{const r=await changeState(s=>{if(el.id==='language')s.collector.language=el.value;else s.collector.locality=el.value;});state=r.state;render();}catch{toast(t('saveFailed'));}}
  if(el.id==='auto-toggle')auto=el.checked;
  if(el.id==='offline-toggle'){simOffline=el.checked;render();}
  if(el.type==='file'&&el.id!=='handover-upload'&&el.files[0]){try{busy=true;const blob=await compressPhoto(el.files[0]);if(!form)return;form.photoBlob=blob;form.photoId=newId('photo');dirty=true;showFormPhoto();document.querySelector('#photo-error').textContent='';}catch(error){document.querySelector('#photo-error').textContent=error.message;}finally{busy=false;}}
});
window.addEventListener('hashchange',navigate);
window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
for(const event of ['online','offline'])window.addEventListener(event,()=>{if(state){readForm();render();}});
const channel='BroadcastChannel'in window?new BroadcastChannel('ewaste-changes'):null;
window.addEventListener('ewaste:saved',()=>channel?.postMessage('changed'));
if(channel)channel.onmessage=async()=>{const updated=await readState();if(updated){state=updated;if(!form)render();}};
setInterval(()=>{if(auto&&!document.hidden&&!form)refresh(true);},60000);
try{
  state=await readState();if(!state)state=(await changeState(()=>{})).state;
  route='';navigate();bindWorkflows({t,money,toast,reload:reloadState,isOffline:()=>simOffline||!navigator.onLine});
  setInterval(()=>{if(state.sync?.code&&!simOffline&&navigator.onLine&&!form&&!document.hidden&&!document.activeElement?.matches('[data-flow-field]'))synchronize().then(reloadState).catch(()=>{});},15000);
  if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{offlineReady=true;if(!form)render();}).catch(()=>{});}
  const modelContext=document.modelContext;
  if(modelContext?.registerTool){const controller=new AbortController();window.addEventListener('pagehide',()=>controller.abort(),{once:true});for(const tool of [
    {name:'read_local_lots',description:'Read lots saved on this device. Does not synchronize or publish them.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async()=>{const latest=await readState();return latest.lots.map(l=>({id:l.id,materialId:l.materialId,weight:l.weight,locality:l.locality,status:l.status}));}},
    {name:'start_lot_creation',description:'Open a new lot form. Does not save or publish a lot.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:async()=>{if(dirty)throw new Error('Save or discard the current form first.');location.hash='create';navigate();return {opened:true,saved:false};}}
  ])Promise.resolve(modelContext.registerTool(tool,{signal:controller.signal})).catch(()=>{});}
}catch(error){app.innerHTML=`<main class="loading"><h1>${t('errorTitle')}</h1><p>${t('storageError')}</p>${button(t('retry'),'retry')}</main>`;console.error('Unable to open local records',error);}
